insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000032', 'de3a0002-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000003', null, 'Welcome! Do not worry, everyone overwaters their first plant. Ask anything.', now() - interval '998 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000033', 'de3a0002-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000008', null, 'Welcome to the community, Lucka. Blueberry auto is a great first choice.', now() - interval '997 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000034', 'de3a0002-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000006', null, 'Hello from Prague! I am also on my first grow, we can learn together.', now() - interval '996 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000075', 'de3a0002-0000-4000-a000-000000000027', 'de3a0000-0000-4000-a000-000000000008', null, 'Lovely. A carbon filter will not work outside, but a balcony is usually fine.', now() - interval '996 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000035', 'de3a0002-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000002', 'de3a0003-0000-4000-a000-000000000034', 'Thank you all, this is so friendly 🙂', now() - interval '994 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000073', 'de3a0002-0000-4000-a000-000000000026', 'de3a0000-0000-4000-a000-000000000007', null, 'Frozen bottles work for a small reservoir, but you have to swap them twice a day. A cheap aquarium chiller is the long-term answer.', now() - interval '898 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000074', 'de3a0002-0000-4000-a000-000000000026', 'de3a0000-0000-4000-a000-000000000001', null, 'Also insulate the bucket and keep it off the warm floor.', now() - interval '895 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000069', 'de3a0002-0000-4000-a000-000000000024', 'de3a0000-0000-4000-a000-000000000001', null, 'So true. I could not remember my EC from last run without notes.', now() - interval '824 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000049', 'de3a0002-0000-4000-a000-000000000017', 'de3a0000-0000-4000-a000-000000000003', null, 'Autos handle 9 °C nights fine, the cold even brings out colour. Just avoid watering in the evening so the roots are not cold and wet at night.', now() - interval '818 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000050', 'de3a0002-0000-4000-a000-000000000017', 'de3a0000-0000-4000-a000-000000000005', null, 'Mine survived 7 °C last year without any problem.', now() - interval '815 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000051', 'de3a0002-0000-4000-a000-000000000017', 'de3a0000-0000-4000-a000-000000000006', 'de3a0003-0000-4000-a000-000000000049', 'Thank you! Leaving her outside then.', now() - interval '812 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000070', 'de3a0002-0000-4000-a000-000000000024', 'de3a0000-0000-4000-a000-000000000009', null, 'Started a journal from day 1 because of posts like this.', now() - interval '800 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000066', 'de3a0002-0000-4000-a000-000000000023', 'de3a0000-0000-4000-a000-000000000005', null, 'BTi (the mosquito bits) in the water works for me, it only targets the larvae and does not hurt the soil life.', now() - interval '617 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000067', 'de3a0002-0000-4000-a000-000000000023', 'de3a0000-0000-4000-a000-000000000003', null, 'A thin layer of sand on top of the mulch also helps, they can not lay eggs as easily.', now() - interval '614 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000068', 'de3a0002-0000-4000-a000-000000000023', 'de3a0000-0000-4000-a000-000000000008', 'de3a0003-0000-4000-a000-000000000066', 'BTi it is. Thanks, Tom!', now() - interval '590 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000026', 'de3a0002-0000-4000-a000-000000000008', 'de3a0000-0000-4000-a000-000000000004', null, 'Lower leaves going first from the tips in usually means the plant is moving nitrogen to the new growth.', now() - interval '498 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000056', 'de3a0002-0000-4000-a000-000000000019', 'de3a0000-0000-4000-a000-000000000006', null, 'First pistils are the best moment 🌸', now() - interval '498 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000027', 'de3a0002-0000-4000-a000-000000000008', 'de3a0000-0000-4000-a000-000000000008', null, 'At day 27 in a small pot she is probably just hungry. Bump the grow nutrient to about 3/4 strength and transplant soon. pH 6.5 is fine in soil.', now() - interval '497 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000057', 'de3a0002-0000-4000-a000-000000000019', 'de3a0000-0000-4000-a000-000000000009', null, 'Looks great! How long until harvest for an auto?', now() - interval '494 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000058', 'de3a0002-0000-4000-a000-000000000019', 'de3a0000-0000-4000-a000-000000000002', 'de3a0003-0000-4000-a000-000000000057', 'The breeder says 9–10 weeks from seed in total, so about a month more.', now() - interval '492 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000028', 'de3a0002-0000-4000-a000-000000000008', 'de3a0000-0000-4000-a000-000000000005', 'de3a0003-0000-4000-a000-000000000027', 'Gave a bit more nutrient and transplanted, new growth is dark green again. Thanks!', now() - interval '470 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000064', 'de3a0002-0000-4000-a000-000000000022', 'de3a0000-0000-4000-a000-000000000009', null, 'I did not know about storage solution. Thanks!', now() - interval '449 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000065', 'de3a0002-0000-4000-a000-000000000022', 'de3a0000-0000-4000-a000-000000000004', null, 'This. In hydro a bad pen can wreck a whole run.', now() - interval '446 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000062', 'de3a0002-0000-4000-a000-000000000021', 'de3a0000-0000-4000-a000-000000000007', null, 'Nice numbers for one plant. Two plants and shorter veg is the right call.', now() - interval '436 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000063', 'de3a0002-0000-4000-a000-000000000021', 'de3a0000-0000-4000-a000-000000000003', null, 'Good dry. 18 °C and 58 % is perfect.', now() - interval '434 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000022', 'de3a0002-0000-4000-a000-000000000007', 'de3a0000-0000-4000-a000-000000000003', null, 'Congratulations on the first harvest! 41 g on a balcony auto is a solid result.', now() - interval '376 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000023', 'de3a0002-0000-4000-a000-000000000007', 'de3a0000-0000-4000-a000-000000000002', null, 'This gives me so much hope for my auto!', now() - interval '373 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000024', 'de3a0002-0000-4000-a000-000000000007', 'de3a0000-0000-4000-a000-000000000001', null, 'Burping twice a day is good for the first week, then less. Nice work.', now() - interval '360 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000025', 'de3a0002-0000-4000-a000-000000000007', 'de3a0000-0000-4000-a000-000000000006', 'de3a0003-0000-4000-a000-000000000024', 'Thanks! I will slow down with burping after this week.', now() - interval '356 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000044', 'de3a0002-0000-4000-a000-000000000015', 'de3a0000-0000-4000-a000-000000000002', null, 'This is really clear, thank you. Is the bloom mix something you make yourself?', now() - interval '331 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000045', 'de3a0002-0000-4000-a000-000000000015', 'de3a0000-0000-4000-a000-000000000008', 'de3a0003-0000-4000-a000-000000000044', 'I mix it from separate amendments, but a ready-made dry bloom mix works the same.', now() - interval '329 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000046', 'de3a0002-0000-4000-a000-000000000015', 'de3a0000-0000-4000-a000-000000000003', null, 'Same idea as my garden beds. Feed the soil, not the plant.', now() - interval '323 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000042', 'de3a0002-0000-4000-a000-000000000013', 'de3a0000-0000-4000-a000-000000000001', null, 'Matches what I see. I would add: watch leaf temperature under LED, it is often 1–2 °C lower than air.', now() - interval '285 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000043', 'de3a0002-0000-4000-a000-000000000013', 'de3a0000-0000-4000-a000-000000000005', null, 'Bookmarked. My cupboard runs 28 °C, time to fix it.', now() - interval '281 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000052', 'de3a0002-0000-4000-a000-000000000018', 'de3a0000-0000-4000-a000-000000000008', null, 'Classic two-spotted spider mites. In flower I would release predatory mites (Phytoseiulus) and wipe the worst leaves with a damp cloth. No sprays on buds.', now() - interval '243.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000053', 'de3a0002-0000-4000-a000-000000000018', 'de3a0000-0000-4000-a000-000000000007', null, 'Also lower the temperature a bit and raise the humidity to 55 %, mites love warm dry air.', now() - interval '242 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000054', 'de3a0002-0000-4000-a000-000000000018', 'de3a0000-0000-4000-a000-000000000004', 'de3a0003-0000-4000-a000-000000000052', 'Ordered predators, they arrive tomorrow. Thank you!', now() - interval '241 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000039', 'de3a0002-0000-4000-a000-000000000012', 'de3a0000-0000-4000-a000-000000000007', null, 'Rising runoff means salts are building up. Do not do a huge flush in coco, just feed at EC 1.4 with 30 % runoff for 2–3 feeds and the runoff will come down.', now() - interval '216.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000040', 'de3a0002-0000-4000-a000-000000000012', 'de3a0000-0000-4000-a000-000000000004', null, 'Agree, coco likes a steady feed. A plain water flush can cause a calcium crash.', now() - interval '215.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000041', 'de3a0002-0000-4000-a000-000000000012', 'de3a0000-0000-4000-a000-000000000001', 'de3a0003-0000-4000-a000-000000000039', 'Did that, runoff is at 2.1 after three feeds. Thanks!', now() - interval '192 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000071', 'de3a0002-0000-4000-a000-000000000025', 'de3a0000-0000-4000-a000-000000000003', null, 'Nice and compact, no stretching. Keep it up.', now() - interval '185 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000072', 'de3a0002-0000-4000-a000-000000000025', 'de3a0000-0000-4000-a000-000000000002', null, 'Cute! Mine looked exactly like this.', now() - interval '182 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000029', 'de3a0002-0000-4000-a000-000000000009', 'de3a0000-0000-4000-a000-000000000007', null, 'Those roots are perfect. What chiller are you using?', now() - interval '169 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000030', 'de3a0002-0000-4000-a000-000000000009', 'de3a0000-0000-4000-a000-000000000004', 'de3a0003-0000-4000-a000-000000000029', 'A small 1/10 HP one, it was the best purchase I ever made for this hobby.', now() - interval '168 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000031', 'de3a0002-0000-4000-a000-000000000009', 'de3a0000-0000-4000-a000-000000000001', null, 'Clean roots in week 5 of flower, respect.', now() - interval '155 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000047', 'de3a0002-0000-4000-a000-000000000016', 'de3a0000-0000-4000-a000-000000000001', null, 'Nice and flat. White Widow stretches about 1.5× for me.', now() - interval '139 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000048', 'de3a0002-0000-4000-a000-000000000016', 'de3a0000-0000-4000-a000-000000000008', null, 'Good luck with the flip!', now() - interval '134 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000055', 'de3a0002-0000-4000-a000-000000000018', 'de3a0000-0000-4000-a000-000000000004', 'de3a0003-0000-4000-a000-000000000052', 'Update: a week later I can not find a single live mite. The predators did their job.', now() - interval '125 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000019', 'de3a0002-0000-4000-a000-000000000006', 'de3a0000-0000-4000-a000-000000000003', null, 'Living soil done right. That fade is perfect.', now() - interval '121 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000020', 'de3a0002-0000-4000-a000-000000000006', 'de3a0000-0000-4000-a000-000000000005', null, 'How much water per pot when you water? I always worry about overwatering big pots.', now() - interval '114 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000021', 'de3a0002-0000-4000-a000-000000000006', 'de3a0000-0000-4000-a000-000000000008', 'de3a0003-0000-4000-a000-000000000020', 'About 10–15 % of the pot volume every 3–4 days, the mulch keeps it even.', now() - interval '112 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000076', 'de3a0002-0000-4000-a000-000000000028', 'de3a0000-0000-4000-a000-000000000001', null, 'Classic nutrient burn. Autos in soil often need only 1/3 to 1/2 of the bottle dose. Give plain water next time and lower the dose.', now() - interval '106.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000077', 'de3a0002-0000-4000-a000-000000000028', 'de3a0000-0000-4000-a000-000000000004', null, 'Agree, burnt tips will not recover but new leaves should be fine.', now() - interval '105 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000016', 'de3a0002-0000-4000-a000-000000000005', 'de3a0000-0000-4000-a000-000000000001', null, 'This is great data, thanks. Did you measure with the tent walls up?', now() - interval '96 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000017', 'de3a0002-0000-4000-a000-000000000005', 'de3a0000-0000-4000-a000-000000000007', 'de3a0003-0000-4000-a000-000000000016', 'Yes, walls closed and lights on for 30 minutes before measuring.', now() - interval '95 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000036', 'de3a0002-0000-4000-a000-000000000011', 'de3a0000-0000-4000-a000-000000000008', null, 'Skunk #1 outdoors is unbeatable for mould resistance.', now() - interval '94 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000018', 'de3a0002-0000-4000-a000-000000000005', 'de3a0000-0000-4000-a000-000000000004', null, 'Saving this. My corners are probably just as bad.', now() - interval '91 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000037', 'de3a0002-0000-4000-a000-000000000011', 'de3a0000-0000-4000-a000-000000000006', null, 'How tall did she get in the garden?', now() - interval '91 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000038', 'de3a0002-0000-4000-a000-000000000011', 'de3a0000-0000-4000-a000-000000000003', 'de3a0003-0000-4000-a000-000000000037', 'About 1.9 m with the net. Without it she would have been taller.', now() - interval '90 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000059', 'de3a0002-0000-4000-a000-000000000020', 'de3a0000-0000-4000-a000-000000000001', null, 'Clean setup. How many tops are you aiming for?', now() - interval '82 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000078', 'de3a0002-0000-4000-a000-000000000028', 'de3a0000-0000-4000-a000-000000000002', 'de3a0003-0000-4000-a000-000000000076', 'New growth is clean, thank you! Half dose from now on.', now() - interval '82 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000060', 'de3a0002-0000-4000-a000-000000000020', 'de3a0000-0000-4000-a000-000000000007', 'de3a0003-0000-4000-a000-000000000059', 'Around 16 under the net.', now() - interval '81 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000061', 'de3a0002-0000-4000-a000-000000000020', 'de3a0000-0000-4000-a000-000000000005', null, 'ScrOG goals. One day I will have the patience.', now() - interval '75 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000012', 'de3a0002-0000-4000-a000-000000000004', 'de3a0000-0000-4000-a000-000000000005', null, 'Daily watering with a small seedling in a big pot is a classic. Water a bigger amount less often.', now() - interval '72 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000013', 'de3a0002-0000-4000-a000-000000000004', 'de3a0000-0000-4000-a000-000000000003', null, 'Lift the pot after watering so you know how heavy wet feels, then wait until it feels light before the next water. For a seedling in 11 l that can be 3–4 days. Water a ring around the stem, 200–300 ml, not the whole pot yet.', now() - interval '71 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000014', 'de3a0002-0000-4000-a000-000000000004', 'de3a0000-0000-4000-a000-000000000009', 'de3a0003-0000-4000-a000-000000000013', 'The lift test makes sense! I will stop watering every day.', now() - interval '68 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000015', 'de3a0002-0000-4000-a000-000000000004', 'de3a0000-0000-4000-a000-000000000002', null, 'Same advice helped me a lot on my first plant 🙂', now() - interval '63 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000008', 'de3a0002-0000-4000-a000-000000000003', 'de3a0000-0000-4000-a000-000000000008', null, 'Beautiful. Shed drying is my favourite method, slow and even.', now() - interval '57 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000009', 'de3a0002-0000-4000-a000-000000000003', 'de3a0000-0000-4000-a000-000000000001', null, 'How long do you usually let it hang at those temps?', now() - interval '54 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000010', 'de3a0002-0000-4000-a000-000000000003', 'de3a0000-0000-4000-a000-000000000003', 'de3a0003-0000-4000-a000-000000000009', 'Around 12–14 days, until the small stems snap. Then into jars.', now() - interval '52 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000011', 'de3a0002-0000-4000-a000-000000000003', 'de3a0000-0000-4000-a000-000000000006', null, 'This is the kind of plant I dream about on my balcony 😄', now() - interval '40 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000001', 'de3a0002-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000007', null, 'Looking great. What PPFD are you at in week 5?', now() - interval '26.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000002', 'de3a0002-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 'de3a0003-0000-4000-a000-000000000001', 'About 850 at the tops, did not want to push more with my CO2-free tent.', now() - interval '25.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000003', 'de3a0002-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000008', null, 'Those tops are stacking. GG4 always rewards patience at the end.', now() - interval '24 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000004', 'de3a0002-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000002', null, 'Wow, I hope mine look like this one day!', now() - interval '19 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000005', 'de3a0002-0000-4000-a000-000000000002', 'de3a0000-0000-4000-a000-000000000004', null, 'Praying hands are usually light or heat. 27 °C is fine, I would raise the light to 45 cm or dim to 80 % and watch the new leaves for two days.', now() - interval '12.8 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000006', 'de3a0002-0000-4000-a000-000000000002', 'de3a0000-0000-4000-a000-000000000007', null, 'With a 150 W board in a 60×60 at 35 cm you are probably over 1000 µmol at the top. Autos in early flower are happy around 600–800.', now() - interval '10.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000007', 'de3a0002-0000-4000-a000-000000000002', 'de3a0000-0000-4000-a000-000000000002', 'de3a0003-0000-4000-a000-000000000006', 'Thank you both! Dimmed to 80 % and raised it a bit, will report back.', now() - interval '9 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000079', 'de3a0002-0000-4000-a000-000000000029', 'de3a0000-0000-4000-a000-000000000001', null, 'GG4, day 36 of flower. Starting to smell up the whole flat.', now() - interval '4 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000080', 'de3a0002-0000-4000-a000-000000000029', 'de3a0000-0000-4000-a000-000000000009', null, 'Amnesia auto, day 16. Third node out and very green!', now() - interval '2.5 hours');
insert into public.comments (id, post_id, author_id, parent_id, body, created_at) values ('de3a0003-0000-4000-a000-000000000081', 'de3a0002-0000-4000-a000-000000000029', 'de3a0000-0000-4000-a000-000000000008', null, 'Purple Kush, day 50 of flower. Fading nicely.', now() - interval '1.5 hours');
