insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 4, 'Topped and started LST. Coco dries out fast now, two small feeds a day with 10–20 % runoff.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000001/demo/veg-coco.jpg']::text[], jsonb_build_object('week', 4, 'day', 28, 'stage', 'vegetative', 'waterings', 1, 'feeds', 2, 'trainings', jsonb_build_array('topping', 'lst'), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 5.9, 'ec', 1.8, 'heightCm', 28, 'from', to_char(current_date - 44, 'YYYY-MM-DD'), 'to', to_char(current_date - 38, 'YYYY-MM-DD')), now() - interval '908.82 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 5, 'Flipped to 12/12 at the end of the week. Canopy is flat, nine main tops.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000001/demo/canopy-scrog.jpg']::text[], jsonb_build_object('week', 5, 'day', 35, 'stage', 'flowering', 'waterings', 2, 'feeds', 1, 'trainings', jsonb_build_array('lst'), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 5.9, 'ec', 1.8, 'heightCm', 39, 'from', to_char(current_date - 37, 'YYYY-MM-DD'), 'to', to_char(current_date - 31, 'YYYY-MM-DD')), now() - interval '735.13 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 6, 'Stretch week. She almost doubled, raised the light to 40 cm. Started bloom nutrients at EC 1.6.', '{}'::text[], jsonb_build_object('week', 6, 'day', 42, 'stage', 'flowering', 'waterings', 2, 'feeds', 1, 'trainings', jsonb_build_array('defoliation'), 'pests', 0, 'notes', 1, 'photos', 0, 'ph', 5.9, 'ec', 1.8, 'heightCm', 58, 'from', to_char(current_date - 30, 'YYYY-MM-DD'), 'to', to_char(current_date - 24, 'YYYY-MM-DD')), now() - interval '569.68 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 7, 'Stretch is over. Did a light lollipop and removed the larf at the bottom.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000001/demo/flowering-pistils.webp']::text[], jsonb_build_object('week', 7, 'day', 49, 'stage', 'flowering', 'waterings', 1, 'feeds', 1, 'trainings', jsonb_build_array('lollipop'), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 5.9, 'ec', 1.8, 'heightCm', 74, 'from', to_char(current_date - 23, 'YYYY-MM-DD'), 'to', to_char(current_date - 17, 'YYYY-MM-DD')), now() - interval '400.71 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 8, 'Buds are forming on every top. Smell is strong now, carbon filter earns its keep. RH 50 % at lights on.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000001/demo/flowering-early-bud.webp']::text[], jsonb_build_object('week', 8, 'day', 56, 'stage', 'flowering', 'waterings', 2, 'feeds', 2, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 5.9, 'ec', 1.8, 'heightCm', 78, 'from', to_char(current_date - 16, 'YYYY-MM-DD'), 'to', to_char(current_date - 10, 'YYYY-MM-DD')), now() - interval '237.88 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000001', 9, 'Week 5 of flower. Frost is coming in. Runoff EC 2.1, so I keep the input at 1.8 and watch it.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000001/demo/flowering-trichomes-close.webp']::text[], jsonb_build_object('week', 9, 'day', 63, 'stage', 'flowering', 'waterings', 2, 'feeds', 1, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 5.9, 'ec', 1.8, 'heightCm', 80, 'from', to_char(current_date - 9, 'YYYY-MM-DD'), 'to', to_char(current_date - 3, 'YYYY-MM-DD')), now() - interval '69.87 hours');
