insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000008', 9, 'Stretch going, about 50 %. Only plain water, the soil does the rest.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000008/demo/vegetative-veg-room.webp']::text[], jsonb_build_object('week', 9, 'day', 63, 'stage', 'flowering', 'waterings', 2, 'feeds', 0, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 'null'::jsonb, 'ec', 'null'::jsonb, 'heightCm', 82, 'from', to_char(current_date - 38, 'YYYY-MM-DD'), 'to', to_char(current_date - 32, 'YYYY-MM-DD')), now() - interval '765.08 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000008', 10, 'Stretch is done. Some fungus gnats after the top dress, put out sticky traps.', '{}'::text[], jsonb_build_object('week', 10, 'day', 70, 'stage', 'flowering', 'waterings', 3, 'feeds', 0, 'trainings', jsonb_build_array(), 'pests', 1, 'notes', 1, 'photos', 0, 'ph', 'null'::jsonb, 'ec', 'null'::jsonb, 'heightCm', 90, 'from', to_char(current_date - 31, 'YYYY-MM-DD'), 'to', to_char(current_date - 25, 'YYYY-MM-DD')), now() - interval '593.41 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000008', 11, 'Purple showing on the sugar leaves with 17 °C nights. Smell is hash and grapes.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000008/demo/flowering-late-cola.webp']::text[], jsonb_build_object('week', 11, 'day', 77, 'stage', 'flowering', 'waterings', 1, 'feeds', 0, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 'null'::jsonb, 'ec', 'null'::jsonb, 'heightCm', 91, 'from', to_char(current_date - 24, 'YYYY-MM-DD'), 'to', to_char(current_date - 18, 'YYYY-MM-DD')), now() - interval '423.24 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000008', 12, 'Buds stacking. Watering every 4 days, about 3 l each time.', '{}'::text[], jsonb_build_object('week', 12, 'day', 84, 'stage', 'flowering', 'waterings', 2, 'feeds', 0, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 0, 'ph', 'null'::jsonb, 'ec', 'null'::jsonb, 'heightCm', 92, 'from', to_char(current_date - 17, 'YYYY-MM-DD'), 'to', to_char(current_date - 11, 'YYYY-MM-DD')), now() - interval '257.13 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000010', 'de3a0000-0000-4000-a000-000000000008', 13, 'Day 45 of flower. Fading starts on the lower fans, right on time for living soil.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000008/demo/nutrition-late-fade.webp']::text[], jsonb_build_object('week', 13, 'day', 91, 'stage', 'flowering', 'waterings', 2, 'feeds', 0, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 'null'::jsonb, 'ec', 'null'::jsonb, 'heightCm', 92, 'from', to_char(current_date - 10, 'YYYY-MM-DD'), 'to', to_char(current_date - 4, 'YYYY-MM-DD')), now() - interval '93.77 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000011', 'de3a0000-0000-4000-a000-000000000009', 1, 'Sprouted on day 3. Dome is off, light at 30 % and 60 cm away.', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000009/demo/seedling-sprout.jpg']::text[], jsonb_build_object('week', 1, 'day', 7, 'stage', 'seedling', 'waterings', 2, 'feeds', 2, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 6.3, 'ec', 0.6, 'heightCm', 3, 'from', to_char(current_date - 15, 'YYYY-MM-DD'), 'to', to_char(current_date - 9, 'YYYY-MM-DD')), now() - interval '208.38 hours');
insert into public.plant_updates (plant_id, owner_id, week_no, body, images, journal_summary, created_at) values ('de3a0001-0000-4000-a000-000000000011', 'de3a0000-0000-4000-a000-000000000009', 2, 'Third node showing. Watering only when the pot feels light, thanks for the tips!', array['https://mlvpmiwvuxgwjssrtxsq.supabase.co/storage/v1/object/public/media/de3a0000-0000-4000-a000-000000000009/demo/germination-seedling-under-led.webp']::text[], jsonb_build_object('week', 2, 'day', 14, 'stage', 'vegetative', 'waterings', 2, 'feeds', 1, 'trainings', jsonb_build_array(), 'pests', 0, 'notes', 1, 'photos', 1, 'ph', 6.3, 'ec', 0.6, 'heightCm', 6, 'from', to_char(current_date - 8, 'YYYY-MM-DD'), 'to', to_char(current_date - 2, 'YYYY-MM-DD')), now() - interval '43.19 hours');
insert into public.tips (id, author_id, body, stage, medium, environment, created_at) values ('de3a0004-0000-4000-a000-000000000001', 'de3a0000-0000-4000-a000-000000000008', 'Drop night temperatures to 16–18 °C in the last two weeks of flower for more colour, but keep the humidity under 50 % to avoid bud rot.', 'flowering', 'soil', 'indoor', now() - interval '220 hours');
