insert into public.strain_reports (strain_id, user_id, plant_id, flowering_days, yield_g, difficulty, rating, medium, tags, notes, created_at) select id, 'de3a0000-0000-4000-a000-000000000003', 'de3a0001-0000-4000-a000-000000000005', 58, 305, 1, 4, 'soil', array['mould-resistant', 'beginner-friendly']::text[], 'Outdoors in South Bohemia, no bud rot even after a wet September. A classic for a reason.', now() - interval '90 hours' from public.strains where slug = 'skunk-1';
