insert into public.strain_reports (strain_id, user_id, plant_id, flowering_days, yield_g, difficulty, rating, medium, tags, notes, created_at) select id, 'de3a0000-0000-4000-a000-000000000003', null, 52, 90, 1, 4, 'soil', array['compact', 'beginner-friendly']::text[], 'Did it in the greenhouse two years ago. Easy, short, done before the autumn rain.', now() - interval '3000 hours' from public.strains where slug = 'northern-lights';
