-- challenge entries and votes (only while the first-grow challenge is open)

-- veteran badge (normally the daily job)

-- backdate what the triggers stamped with now()
set local session_replication_role = replica;

update public.posts p set solved_at = c.created_at + interval '3 hours'
  from public.comments c where c.id = p.accepted_comment_id and p.author_id::text like 'de3a0000-%';

update public.user_badges b set earned_at = x.at from (
  select author_id as u, 'first_post' as badge, min(created_at) as at from public.posts group by author_id
  union all select c.author_id, 'first_answer', min(p.solved_at) from public.posts p join public.comments c on c.id = p.accepted_comment_id group by c.author_id
  union all select user_id, 'challenger', min(created_at) from public.challenge_entries group by user_id
  union all select owner_id, 'first_harvest', min(updated_at) from public.public_plants where harvest_dry_g is not null group by owner_id
  union all select owner_id, 'diary_keeper', min(created_at) from (
    select owner_id, created_at, row_number() over (partition by plant_id order by created_at) rn from public.plant_updates) u where rn = 6 group by owner_id
  union all select author_id, 'welcome', max(created_at) from public.comments group by author_id
) x where b.user_id = x.u and b.badge_id = x.badge and b.user_id::text like 'de3a0000-%';

update public.notifications n set created_at = c.created_at from public.comments c
  where n.comment_id = c.id and n.type in ('comment', 'reply');
update public.notifications n set created_at = p.solved_at from public.posts p
  where n.post_id = p.id and n.type = 'accepted' and p.solved_at is not null;
update public.notifications n set created_at = r.at from (
  select user_id, post_id, min(created_at) at from public.post_reactions group by user_id, post_id) r
  where n.type = 'reaction' and n.actor_id = r.user_id and n.post_id = r.post_id;
update public.notifications n set created_at = f.created_at from public.follows f
  where n.type = 'follow' and f.follower_id = n.actor_id and f.following_id = n.user_id;
update public.notifications n set created_at = u.created_at from public.plant_updates u
  where n.type = 'update' and (n.meta ->> 'update_id')::uuid = u.id;
update public.notifications n set created_at = least(t.created_at + interval '5 hours', now()) from public.tips t
  where n.type = 'tip_vote' and (n.meta ->> 'tip_id')::uuid = t.id;
update public.notifications n set created_at = b.earned_at from public.user_badges b
  where n.type = 'badge' and n.user_id = b.user_id and b.badge_id = n.meta ->> 'badge';

-- demo users have seen their older notifications, the admin keeps the last few days unread
update public.notifications set read_at = created_at + interval '2 hours'
  where created_at < now() - interval '1 day' and user_id::text like 'de3a0000-%';
update public.notifications set read_at = created_at + interval '3 hours'
  where created_at < now() - interval '4 days' and actor_id::text like 'de3a0000-%' and read_at is null;

set local session_replication_role = origin;

-- rate-limit log rows written by this seed
delete from private.rate_log where at = now();

commit;
